files={'FIRST5-3359-ACTUAL-INDEPENDENT-REVIEW.md': '', 'FIRST5-3359-RELEASE-RECEIPT-CANDIDATE.json': ''}
import os,json,base64,hashlib,subprocess
from pathlib import Path
r=Path('/dataset/shaoshitong/search-r1-rl/bapo-aligned-cohost-node11-v11-20261009');assert os.uname().nodename=='h100-11'
d=r/'evidence/first5-independent-review3359-20261009-2210';d.mkdir(exist_ok=True);assert d.resolve()==d
for n,b in files.items():
 p=d/n;raw=base64.b64decode(b)
 if p.exists():assert p.read_bytes()==raw and not p.is_symlink()
 else:
  with p.open('xb')as f:f.write(raw);f.flush();os.fsync(f.fileno())
env=dict(os.environ,CUDA_VISIBLE_DEVICES='',PYTHONPATH=str(r/'repo'),HF_HUB_OFFLINE='1',TRANSFORMERS_OFFLINE='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1',PYTHONDONTWRITEBYTECODE='1');env.pop('LD_LIBRARY_PATH',None)
tool=r/'tools/deployment/first5-node11-3359-v2/publish_first5_release.py'
receipt=d/'FIRST5-3359-RELEASE-RECEIPT-CANDIDATE.json';report=d/'FIRST5-3359-ACTUAL-INDEPENDENT-REVIEW.md'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(receipt)=='f4b7ee5063576d9c486f1833eb47bd9d7b5c292be64d6d1f13e66131903a4f3c'
assert sha(report)=='729dac5e0ec64be9f97df839cbaa644c19682c166b573923c7b2b2efe21b04cc'
planout=r/'evidence/first5-release3359-v2-20261009-2215'
p=subprocess.run([str(r/'env/bin/python'),'-B',str(tool),'prepare','--receipt',str(receipt),'--receipt-sha256',sha(receipt),'--report-sha256',sha(report),'--cpu-evidence-sha256','cee8e9e4d671fd998ad1474af98f7f05b353db0d7867dfe9c7c3e96e3fd21198','--output',str(planout)],cwd=r/'repo',env=env,capture_output=True,text=True)
print(json.dumps({'phase':'prepare','exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}),flush=True)
assert p.returncode==0
plan=planout/'release-plan.json'
p=subprocess.run([str(r/'env/bin/python'),'-B',str(tool),'publish','--plan',str(plan),'--plan-sha256',sha(plan),'--payload-sha256',sha(receipt)],cwd=r/'repo',env=env,capture_output=True,text=True)
print(json.dumps({'phase':'publish','exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}),flush=True)
raise SystemExit(p.returncode)
